on conflict (id) do update set
  airline = excluded.airline, role = excluded.role, aircraft = excluded.aircraft,
  region = excluded.region, location = excluded.location, type = excluded.type,
  min_hours = excluded.min_hours, rated = excluded.rated, salary = excluded.salary,
  verified = true, apply_url = excluded.apply_url, reqs = excluded.reqs,
  category = excluded.category, posted_at = excluded.posted_at, deadline = excluded.deadline;

-- remove verified listings that left the catalog (closed/withdrawn)
delete from public.jobs where verified = true and id not in (101, 102, 103, 104, 111, 112, 113, 114, 115, 116, 117, 121, 131, 132, 133, 141, 142, 143, 151, 152, 161, 162, 163, 221, 222, 223, 224, 373, 374, 375, 376, 225, 226, 227, 228, 229, 171, 172, 181, 191, 201, 202, 211, 212, 233, 234, 241, 243, 244, 245, 251, 252, 253, 254, 256, 261, 348, 349, 350, 351, 352, 353, 354, 355, 356, 357, 358, 359, 360, 361, 372, 379, 380, 381, 382, 383, 384, 385, 386, 387, 388, 389, 390, 391, 392, 378, 362, 363, 364, 377, 365, 366, 367, 368, 369, 371, 262, 263, 264, 271, 272, 273, 274, 281, 282, 283, 284, 285, 286, 287, 288, 289, 290, 301, 302, 303, 304, 305, 306, 307, 308, 309, 311, 312, 313, 314, 320, 321, 322, 323, 324, 325, 393, 394, 326, 327, 328, 329, 330, 331, 332, 333, 334, 335, 336, 337, 338, 339, 340, 341, 342, 343, 344, 345, 346, 347);

-- keep the identity sequence clear of catalog ids (recruiter posts get ids >= 1000)
select setval(pg_get_serial_sequence('public.jobs', 'id'),
  greatest((select coalesce(max(id), 0) + 1 from public.jobs), 1000), false);

commit;

-- sanity check: should match data.js (156 verified listings)
select count(*) filter (where verified) as verified_jobs,
       count(*) filter (where not verified) as recruiter_posts
from public.jobs;
